class UnionFind:
    def __init__(self, size):
        self.parent = {}
        self.rank = {}
        for i in range(size):
            self.parent[i] = i
            self.rank[i] = 1

    def find(self, x):
        if x != self.parent[x]:
            x = self.find(self.parent[x])
        return x

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py: return
        if self.rank[px] >= self.rank[py]:
            self.parent[py] = px
            self.rank[px] += self.rank[py]
        else:
            self.parent[px] = py
            self.rank[py] += self.rank[px]

